WHERE
{
 VALUES ?subject { <http://dbpedia.org/resource/Niccolò_Paganini> }


 # rdf:type ?typeTimeExpression .
 #FILTER ( ?typeTimeExpression != mtp:TimeExpression ) .
 OPTIONAL {
